:root {
  --bg-base: #0a0a0a;
  --bg-surface: #111111;
  --bg-card: #1f1f1f;
  --border: #2a2a2a;
  --text: #fafafa;
  --text-muted: #a1a1aa;
  --accent: #0ea5e9;
  --success: #22c55e;
  --danger: #ef4444;
  --warning: #f59e0b;

  /* Uma cor por fonte de receita — a mesma em pílula, gráfico e avatar. */
  --src-empresa: #0ea5e9;
  --src-impressionart: #8b5cf6;
  --src-moto: #f59e0b;
  --src-mos: #22c55e;
  --src-nata: #ec4899;

  --fonte: 'Manrope', sans-serif;
  --fonte-titulo: 'Sora', sans-serif;
  --fonte-mono: 'JetBrains Mono', monospace;
}

body { background: var(--bg-base); color: var(--text); font-family: var(--fonte); }

/* Número em tabela, card ou badge nunca "dança" ao atualizar. */
.bs-num { font-variant-numeric: tabular-nums; }

.bs-segredos { width: min(460px, 100%); display: flex; flex-direction: column; gap: 10px; }

.bs-segredo { padding: 12px 14px; border: 1px solid var(--border); border-radius: 10px; background: var(--bg-base); }
.bs-segredo-rotulo {
  margin-bottom: 6px;
  font-size: 11px; text-transform: uppercase; letter-spacing: 0.06em; color: var(--text-muted);
}

.bs-segredo-linha { display: flex; align-items: center; gap: 10px; }

/* min-width: 0 no item flexível é o que permite truncar uma chave longa. */
.bs-segredo-valor {
  flex: 1; min-width: 0;
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
  font-family: var(--fonte-mono); font-size: 14px; color: var(--text);
}
/* Mascarado é outro texto, não o mesmo com fonte trocada: enquanto oculto, o
   valor real não está no DOM. */
.bs-oculto { letter-spacing: 0.15em; color: var(--text-muted); }

.bs-segredo-btn {
  display: grid; place-items: center; flex-shrink: 0;
  width: 32px; height: 32px; border-radius: 8px;
  border: 1px solid var(--border); background: var(--bg-card); color: var(--text-muted);
}
.bs-segredo-btn:hover { color: var(--text); border-color: var(--accent); }
.bs-segredo-btn:disabled { opacity: 0.5; }
.bs-segredo-ic { width: 14px; height: 14px; }

